#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

# The family devices set-up (#40, docs/family-devices.md): the parts only
# Craig can do, run on his Mac from a checkout of main.
#
#   infra/zero-trust/wizard.sh            first run: the Zero Trust root's
#                                         imports and first apply, the GitHub
#                                         variables, a Deploy run
#   infra/zero-trust/wizard.sh inspect    after both iPhones trust the Gateway
#                                         certificate: inspect_https = true
#   infra/zero-trust/wizard.sh lock       later, optional: lock_client = true
#
# It works on the checkout it sits in (REPO= names another). The only files
# it writes in the repository are gitignored tfvars files. Every import, apply
# and deploy approval asks first; answering y is the approval. Safe to run
# again after a failure: what the state already has is left as it is.

MODE="${1:-first}"
REPO="${REPO:-$(cd "$(dirname "${BASH_SOURCE[0]}")/../.." && pwd)}"
ZT="$REPO/infra/zero-trust"
TFVARS="$ZT/zero-trust.auto.tfvars"
ACCOUNT_ID="ada2e308f4d17f259887ed31aa91cdf3"
CF_API="https://api.cloudflare.com/client/v4"
TOKEN_FILE="${CLOUDFLARE_API_TOKEN_FILE:-$HOME/.config/craigdevjohnson/cloudflare_api_token}"
export AWS_PROFILE="${AWS_PROFILE:-workloads-admin}"
export GH_REPO="CraigDevJohnson/the-lobby"
WORK="$(mktemp -d)"
PLAN="$WORK/zero-trust.tfplan"
trap 'rm -rf "$WORK"' EXIT

case "$MODE" in
  first)   TOTAL_STAGES=10 ;;
  inspect) TOTAL_STAGES=3 ;;
  lock)    TOTAL_STAGES=2 ;;
  *) printf 'usage: %s [first|inspect|lock]\n' "$0" >&2; exit 2 ;;
esac

# ── helpers for these stages ──────────────────────────────────────────────

fail() { printf '  %s✗ %s%s\n' "$RED" "$1" "$RESET" >&2; exit 1; }
ok()   { printf '  %s✓%s %s\n' "$GREEN" "$RESET" "$1"; }

# cf PATH: GET from the Cloudflare API with the token; prints the JSON body.
cf() { curl -sS -H "Authorization: Bearer $CLOUDFLARE_API_TOKEN" "$CF_API$1"; }
cf_ok() { jq -e '.success == true' >/dev/null 2>&1 <<<"$1"; }
cf_error() { jq -r '.errors[0].message // "unknown error"' <<<"$1"; }

tf() { tofu -chdir="$ZT" "$@"; }
in_state() { tf state list 2>/dev/null | grep -Fxq -- "$1"; }

# take_over ADDRESS ID "what": imports what the account already has, unless
# the state has it. Asks first.
take_over() {
  local address="$1" id="$2" what="$3"
  if in_state "$address"; then
    ok "$what is already in the state ($address)"
    return 0
  fi
  if confirm "Import $what into $address (id $id)?"; then
    tf import -input=false "$address" "$id"
    ok "imported $address"
  else
    warn "left $what alone; the plan will want to create a new one"
  fi
}

# tfvars_drop FILE KEY... prints FILE without its assignments of the KEYs,
# whether on one line, as a list over several lines or as a heredoc, and
# without a commented one-line example of them.
tfvars_drop() {
  local file="$1" keys
  shift
  keys="$(IFS='|'; printf '%s' "$*")"
  awk -v keys="$keys" '
    heredoc { if ($0 ~ ("^[ \t]*" term "[ \t]*$")) heredoc = 0; next }
    list    { if ($0 ~ /\]/) list = 0; next }
    $0 ~ ("^#[ \t]*(" keys ")[ \t]*=") { next }
    $0 ~ ("^[ \t]*(" keys ")[ \t]*=") {
      if (match($0, /<<-?[A-Za-z_][A-Za-z0-9_]*/)) {
        term = substr($0, RSTART, RLENGTH); sub(/^<<-?/, "", term); heredoc = 1; next
      }
      rest = $0; sub(/^[^=]*=/, "", rest)
      if (rest ~ /^[ \t]*\[/ && rest !~ /\]/) list = 1
      next
    }
    { print }
  ' "$file"
}

# tfvars_set KEY VALUE upserts `KEY = VALUE` in zero-trust.auto.tfvars,
# replacing a commented example line too.
tfvars_set() {
  local key="$1" value="$2" tmp
  tmp=$(mktemp)
  tfvars_drop "$TFVARS" "$key" > "$tmp"
  printf '%s = %s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$TFVARS"
  ok "$key = $value in ${TFVARS#"$REPO/"}"
}

# preflight: the Mac, the checkout, the AWS session, the token, gh.
preflight() {
  local tool missing=() verify probe
  for tool in git tofu aws gh curl jq; do
    if ! command -v "$tool" >/dev/null 2>&1; then missing+=("$tool"); fi
  done
  if (( ${#missing[@]} )); then fail "missing on this Mac: ${missing[*]} (brew install ${missing[*]})"; fi
  ok "git, tofu, aws, gh, curl and jq are installed"

  if [[ ! -e "$REPO/.git" ]]; then fail "no checkout at $REPO (set REPO=... to another path)"; fi
  git -C "$REPO" fetch -q origin main
  if ! git -C "$REPO" merge-base --is-ancestor origin/main HEAD; then
    warn "the checkout at $REPO is behind origin/main"
    say "Bring it up to date in another terminal, then press Enter:"
    say "  git -C $REPO pull --ff-only origin main"
    say "or stop here (Ctrl-C) and run the wizard from a fresh worktree of main:"
    say "  git -C $REPO worktree add --detach $HOME/Projects/the-lobby-main origin/main"
    say "  $HOME/Projects/the-lobby-main/infra/zero-trust/wizard.sh $MODE"
    pause
    git -C "$REPO" merge-base --is-ancestor origin/main HEAD || fail "still behind origin/main"
  fi
  if [[ ! -f "$ZT/versions.tf" ]]; then fail "$ZT is missing: the-lobby PR #47 is not in this checkout yet"; fi
  ok "$REPO is at origin/main or ahead of it, with infra/zero-trust"

  if ! aws sts get-caller-identity --profile "$AWS_PROFILE" >/dev/null 2>&1; then
    say "The AWS session for the state bucket has expired; signing in:"
    aws sso login --profile "$AWS_PROFILE"
  fi
  ok "AWS profile $AWS_PROFILE is signed in (the state bucket only)"

  if [[ -z "${CLOUDFLARE_API_TOKEN:-}" ]]; then
    if [[ ! -r "$TOKEN_FILE" ]]; then fail "no Cloudflare token: set CLOUDFLARE_API_TOKEN or put it in $TOKEN_FILE"; fi
    CLOUDFLARE_API_TOKEN="$(cat "$TOKEN_FILE")"
  fi
  export CLOUDFLARE_API_TOKEN
  verify="$(cf /user/tokens/verify)"
  cf_ok "$verify" || fail "the Cloudflare token is not valid: $(cf_error "$verify")"
  ok "the Cloudflare token is $(jq -r .result.status <<<"$verify")"

  probe="$(cf "/accounts/$ACCOUNT_ID/gateway/locations")"
  if ! cf_ok "$probe"; then
    warn "the token cannot read Zero Trust: $(cf_error "$probe")"
    say "Edit the token: add Account › Zero Trust › Edit, save, then press Enter."
    open_url "https://dash.cloudflare.com/profile/api-tokens"
    pause
    probe="$(cf "/accounts/$ACCOUNT_ID/gateway/locations")"
    cf_ok "$probe" || fail "the token still cannot read Zero Trust: $(cf_error "$probe")"
  fi
  ok "the token can read Zero Trust"

  gh auth status >/dev/null 2>&1 || fail "gh is not signed in: gh auth login"
  ok "gh is signed in; variables go to $GH_REPO"
}

# plan_and_apply: plans the root, checks it stays inside Cloudflare Zero
# Trust (ADR 0009), shows one line per change, asks, applies.
plan_and_apply() {
  local outside changes
  say "Planning..."
  if ! tf plan -input=false -out="$PLAN" >"$WORK/plan.log" 2>&1; then
    cat "$WORK/plan.log"
    fail "tofu plan failed"
  fi
  tf show -json "$PLAN" > "$WORK/plan.json"
  outside="$(jq -r '.resource_changes[].type' "$WORK/plan.json" | grep -v '^cloudflare_zero_trust_' || true)"
  if [[ -n "$outside" ]]; then fail "the plan touches types outside Cloudflare Zero Trust: $outside"; fi
  changes="$(jq '[.resource_changes[] | select(.change.actions != ["no-op"])] | length' "$WORK/plan.json")"
  if [[ "$changes" == "0" ]]; then
    ok "nothing to change: the account already matches the root"
    return 0
  fi
  say "The plan, one line per change (all Cloudflare Zero Trust, as ADR 0009 requires):"
  jq -r '.resource_changes[] | select(.change.actions != ["no-op"]) | "      \(.change.actions | join("+"))  \(.address)"' "$WORK/plan.json"
  if confirm "Read the whole plan first (q leaves the pager)?"; then
    tf show "$PLAN" | less -R
  fi
  if ! confirm "Apply these $changes change(s) to the live Cloudflare account?"; then
    fail "not applied; nothing has changed. Run the wizard again when ready."
  fi
  tf apply -input=false "$PLAN"
  ok "applied"
}

# review_run RUN STATE COMMENT approves or rejects (STATE) every environment
# the Deploy run RUN is waiting on. Fails when it is waiting on none.
review_run() {
  local run="$1" state="$2" comment="$3" env_id args=()
  while read -r env_id; do
    if [[ -n "$env_id" ]]; then args+=(-F "environment_ids[]=$env_id"); fi
  done < <(gh api "repos/$GH_REPO/actions/runs/$run/pending_deployments" -q '.[].environment.id' 2>/dev/null || true)
  (( ${#args[@]} )) || return 1
  gh api -X POST "repos/$GH_REPO/actions/runs/$run/pending_deployments" "${args[@]}" \
    -f state="$state" -f comment="$comment" >/dev/null
}

# deploy_result RUN says how the Deploy run RUN ended, and when it did not
# succeed leaves the way back in the closing list: another run.
deploy_result() {
  local run="$1" conclusion
  conclusion="$(gh run view "$run" --json conclusion -q .conclusion 2>/dev/null || true)"
  if [[ "$conclusion" == "success" ]]; then
    ok "Deploy run $run finished: success"
  else
    warn "Deploy run $run finished: ${conclusion:-unknown} (https://github.com/$GH_REPO/actions/runs/$run)"
    SKIPPED+=("Deploy run $run ended '${conclusion:-unknown}', so a site may not have the new settings yet. Read the run, then run this wizard again (it leaves what is done alone):  $0")
  fi
}

# follow_deploy RUN waits for the Deploy run RUN to reach production and asks
# to approve it there. Production deploys one run at a time (the workflow's
# deploy-production concurrency group), and a run waiting for its reviewer
# holds that line, so RUN would wait behind an older run for good: an older
# run from main waiting meanwhile (the merge's own, started before the
# variables were set) is rejected. The caller's confirm covers that.
follow_deploy() {
  local run="$1" status="" id envs approve
  say "Run $run: https://github.com/$GH_REPO/actions/runs/$run"
  say "Waiting for dev to deploy and production to ask for approval (a few minutes)..."
  for _ in $(seq 1 80); do
    status="$(gh run view "$run" --json status -q .status 2>/dev/null || true)"
    if [[ "$status" == "waiting" || "$status" == "completed" ]]; then break; fi
    # Only older runs from main: a run from a tag or another branch is a
    # deliberate redeploy of another commit and is left for you to review.
    for id in $(gh run list --workflow deploy.yml --branch main --status waiting --json databaseId -q '.[].databaseId' 2>/dev/null || true); do
      if (( id >= run )); then continue; fi
      if review_run "$id" rejected "Superseded by Deploy run $run from infra/zero-trust/wizard.sh"; then
        ok "rejected production for the older run $id, so this one can go next"
      fi
    done
    sleep 15
  done
  # The command that approves it by hand, printed when this stage cannot.
  approve="gh api -X POST repos/$GH_REPO/actions/runs/$run/pending_deployments -F \"environment_ids[]=\$(gh api repos/$GH_REPO/actions/runs/$run/pending_deployments -q '.[0].environment.id')\" -f state=approved -f comment=Approved"
  case "$status" in
    waiting)
      envs="$(gh api "repos/$GH_REPO/actions/runs/$run/pending_deployments" -q '[.[].environment.name] | join(", ")' 2>/dev/null || true)"
      if confirm "Dev is deployed. Approve the ${envs:-production} deploy of run $run now?"; then
        if review_run "$run" approved "Approved from infra/zero-trust/wizard.sh"; then
          say "Approved; waiting for production to finish..."
          gh run watch "$run" --exit-status >/dev/null || true
          deploy_result "$run"
        else
          warn "the approval did not go through"
          SKIPPED+=("approve production for Deploy run $run:  $approve")
        fi
      else
        SKIPPED+=("approve production for Deploy run $run:  $approve")
      fi
      ;;
    completed)
      deploy_result "$run"
      ;;
    *)
      warn "the run is still '$status' after 20 minutes (https://github.com/$GH_REPO/actions/runs/$run)"
      SKIPPED+=("once Deploy run $run waits for production, approve it:  $approve")
      ;;
  esac
}

# ── first run ─────────────────────────────────────────────────────────────

if [[ "$MODE" == "first" ]]; then
  banner "Family devices: the Gateway, the variables, the deploy"

  stage "Check this Mac"
  preflight

  stage "The two adults' addresses"
  say "The Zero Trust root reads them from the gitignored zero-trust.auto.tfvars: who may"
  say "enroll an iPhone. The same two go on the /admin page's list in GitHub (stage 8)."
  EMAILS_JSON=""
  if [[ -f "$TFVARS" ]]; then
    say "The file exists already:"
    sed 's/^/      /' "$TFVARS"
    if confirm "Keep it as it is?"; then
      # The list as written, over one line or several, then checked: it also
      # becomes the /admin page's list in GitHub, which must be JSON.
      EMAILS_JSON="$(awk '/^[ \t]*enrollment_emails[ \t]*=/ { on = 1; sub(/^[^=]*=/, "") } on { printf "%s", $0; if ($0 ~ /\]/) exit }' "$TFVARS")"
      if ! EMAILS_JSON="$(jq -ce 'if type == "array" and length > 0 and all(.[]; type == "string" and test("^[^@[:space:]]+@[^@[:space:]]+[.][^@[:space:]]+$")) then . else error("not a list of addresses") end' <<<"$EMAILS_JSON" 2>/dev/null)"; then
        warn "its enrollment_emails is not a plain list of addresses, so enter them again"
        EMAILS_JSON=""
      fi
    fi
  fi
  if [[ -z "$EMAILS_JSON" ]]; then
    ADULT_1="" ADULT_2=""
    ask ADULT_1 "First adult's address:"
    ask ADULT_2 "Second adult's address (Enter if there is only one):"
    if [[ "$ADULT_1" != *@* ]]; then fail "$ADULT_1 is not an email address"; fi
    if [[ -n "$ADULT_2" ]]; then
      if [[ "$ADULT_2" != *@* ]]; then fail "$ADULT_2 is not an email address"; fi
      EMAILS_JSON="$(jq -cn --arg a "$ADULT_1" --arg b "$ADULT_2" '[$a, $b]')"
    else
      EMAILS_JSON="$(jq -cn --arg a "$ADULT_1" '[$a]')"
    fi
    if [[ ! -f "$TFVARS" ]]; then cp "$ZT/zero-trust.auto.tfvars.example" "$TFVARS"; fi
    tfvars_set enrollment_emails "$EMAILS_JSON"
    if ! grep -qE '^do_not_inspect_app_ids' "$TFVARS"; then tfvars_set do_not_inspect_app_ids "[]"; fi
  fi
  note "do_not_inspect_app_ids stays empty until an app breaks under inspection (#40)."

  stage "Initialise the root"
  say "tofu init connects infra/zero-trust to its state key in the AWS bucket and installs"
  say "the Cloudflare provider."
  if ! tf init -input=false >"$WORK/init.log" 2>&1; then
    cat "$WORK/init.log"
    fail "tofu init failed"
  fi
  ok "initialised (state key the-lobby/zero-trust/terraform.tfstate)"

  stage "Take over: DNS locations"
  say "Gateway may already have a location (it makes one on first use). The root declares two,"
  say "Kids and Adults, neither the default. Only a location already named Kids or Adults is"
  say "imported; anything else, including a default one, is left alone."
  LOCATIONS="$(cf "/accounts/$ACCOUNT_ID/gateway/locations")"
  cf_ok "$LOCATIONS" || fail "could not list locations: $(cf_error "$LOCATIONS")"
  if [[ "$(jq '.result | length' <<<"$LOCATIONS")" == "0" ]]; then
    say "No locations yet; the apply creates Kids and Adults."
  else
    jq -r '.result[] | "      \(.name)  id \(.id)  default \(.client_default)  doh \(.doh_subdomain // "-")"' <<<"$LOCATIONS"
    for key in kids adults; do
      name="$(tr '[:lower:]' '[:upper:]' <<<"${key:0:1}")${key:1}"
      id="$(jq -r --arg n "$name" '[.result[] | select(.name == $n)][0].id // empty' <<<"$LOCATIONS")"
      if [[ -n "$id" ]]; then
        take_over "cloudflare_zero_trust_dns_location.location[\"$key\"]" "$ACCOUNT_ID/$id" "the $name location"
      fi
    done
  fi

  stage "Take over: the Gateway root certificate"
  say "Accounts made since October 2024 already have one. It is imported, never generated"
  say "twice: Cloudflare allows three generations a day and ten available at once."
  CERTS="$(cf "/accounts/$ACCOUNT_ID/gateway/certificates")"
  cf_ok "$CERTS" || fail "could not list certificates: $(cf_error "$CERTS")"
  if [[ "$(jq '.result | length' <<<"$CERTS")" == "0" ]]; then
    say "No certificate yet; the apply generates one."
  else
    jq -r '.result[] | "      id \(.id)  \(.type)  \(.binding_status)  in use \(.in_use)  expires \(.expires_on)"' <<<"$CERTS"
    CERT_ID="$(jq -r '([.result[] | select(.in_use == true)] + [.result[] | select(.binding_status == "available")] + .result)[0].id' <<<"$CERTS")"
    take_over cloudflare_zero_trust_gateway_certificate.gateway "$ACCOUNT_ID/$CERT_ID" "the certificate $CERT_ID"
  fi

  stage "Take over: device enrollment and the Gateway settings"
  say "The dashboard's Device enrollment permissions page is an Access application of type"
  say "warp; if one exists it is imported, and the apply replaces its policies with one,"
  say "Family adults. The account's Gateway settings always exist and are always imported."
  APPS="$(cf "/accounts/$ACCOUNT_ID/access/apps")"
  cf_ok "$APPS" || fail "could not list Access applications: $(cf_error "$APPS")"
  WARP_IDS="$(jq -r '.result[] | select(.type == "warp") | .id' <<<"$APPS")"
  WARP_COUNT="$(grep -c . <<<"$WARP_IDS" || true)"
  case "$WARP_COUNT" in
    0) say "No enrollment application yet; the apply creates it." ;;
    1) take_over cloudflare_zero_trust_access_application.enrollment "accounts/$ACCOUNT_ID/$WARP_IDS" "the enrollment application" ;;
    *) warn "more than one warp application; importing the first and leaving the rest:"
       jq -r '.result[] | select(.type == "warp") | "      \(.name)  id \(.id)"' <<<"$APPS"
       take_over cloudflare_zero_trust_access_application.enrollment "accounts/$ACCOUNT_ID/$(head -n1 <<<"$WARP_IDS")" "the first enrollment application" ;;
  esac
  take_over cloudflare_zero_trust_gateway_settings.account "$ACCOUNT_ID" "the Gateway settings"
  note "The device settings (the proxy toggles) cannot be imported; the apply writes them, off."

  stage "Plan and apply the root (inspection stays off)"
  say "inspect_https is false on this first apply: nothing is decrypted until the iPhones"
  say "trust the certificate (the inspect run, later)."
  plan_and_apply
  tf output -json gateway_certificate_status | jq -r '"      certificate \(.id): \(.binding_status), in use \(.in_use), expires \(.expires_on)"'

  stage "The GitHub variables for the /admin page"
  KIDS_DOH_URL="$(tf output -raw kids_doh_url)"
  ADULTS_DOH_URL="$(tf output -raw adults_doh_url)"
  GATEWAY_ROOT_CA_PEM="$(tf output -raw gateway_root_ca_pem)"
  say "From the apply's outputs:"
  say "  KIDS_DOH_URL         $KIDS_DOH_URL"
  say "  ADULTS_DOH_URL       $ADULTS_DOH_URL"
  say "  GATEWAY_ROOT_CA_PEM  $(printf '%s' "$GATEWAY_ROOT_CA_PEM" | wc -c | tr -d ' ') bytes of PEM"
  set_var KIDS_DOH_URL "$KIDS_DOH_URL"
  set_var ADULTS_DOH_URL "$ADULTS_DOH_URL"
  set_var GATEWAY_ROOT_CA_PEM "$GATEWAY_ROOT_CA_PEM"
  for name in ADMIN_EMAILS_DEV ADMIN_EMAILS_PROD; do
    if current="$(gh variable get "$name" 2>/dev/null)"; then
      ok "$name is already set ($(jq -r 'length' <<<"$current" 2>/dev/null || echo '?') address(es)); left as it is"
    else
      set_var "$name" "$EMAILS_JSON"
    fi
  done

  stage "This Mac's own copies (optional)"
  say "task infra:dev:plan on this Mac reads infra/environments/dev/secrets.auto.tfvars, and"
  say "would plan the /admin application away without these. The deploys run in Actions and"
  say "do not need this; say no unless you plan from the Mac. Any admin_emails, kids_doh_url,"
  say "adults_doh_url or gateway_root_ca_pem already in those files is replaced."
  if confirm "Write admin_emails and the three profile settings into dev's and prod's secrets.auto.tfvars?"; then
    for env in dev prod; do
      f="$REPO/infra/environments/$env/secrets.auto.tfvars"
      if [[ ! -f "$f" ]]; then note "no $f; skipped"; continue; fi
      tmp=$(mktemp)
      awk '/^# family devices \(wizard\)$/{skip=1} /^# end family devices$/{skip=0; next} !skip' "$f" > "$tmp"
      tfvars_drop "$tmp" admin_emails kids_doh_url adults_doh_url gateway_root_ca_pem > "$tmp.kept"
      {
        cat "$tmp.kept"
        printf '# family devices (wizard)\n'
        printf 'admin_emails        = %s\n' "$EMAILS_JSON"
        printf 'kids_doh_url        = "%s"\n' "$KIDS_DOH_URL"
        printf 'adults_doh_url      = "%s"\n' "$ADULTS_DOH_URL"
        printf 'gateway_root_ca_pem = <<-EOT\n%s\nEOT\n' "$GATEWAY_ROOT_CA_PEM"
        printf '# end family devices\n'
      } > "$f"
      rm -f "$tmp" "$tmp.kept"
      ok "wrote ${f#"$REPO/"}"
    done
  else
    note "skipped"
  fi

  stage "Deploy the page"
  say "The deploy at the merge ran before the variables existed, so neither site has them yet."
  say "A new Deploy run from main picks them up: dev applies on its own, production waits for"
  say "your approval, which this stage gives through the API."
  say "Production takes one run at a time, and a run waiting for approval holds the line, so an"
  say "older run from main still waiting there (the merge's own) is rejected: it has nothing this"
  say "one lacks. A run from a tag or another branch is left alone."
  if confirm "Start a Deploy run from main now, rejecting any older run still waiting for production?"; then
    BEFORE="$(gh run list --workflow deploy.yml --branch main --event workflow_dispatch -L 1 --json databaseId -q '.[0].databaseId // ""')"
    RUN_ID=""
    if gh workflow run deploy.yml --ref main; then
      for _ in $(seq 1 20); do
        sleep 3
        RUN_ID="$(gh run list --workflow deploy.yml --branch main --event workflow_dispatch -L 1 --json databaseId -q '.[0].databaseId // ""')"
        if [[ -n "$RUN_ID" && "$RUN_ID" != "$BEFORE" ]]; then break; fi
        RUN_ID=""
      done
    fi
    if [[ -n "$RUN_ID" ]]; then
      follow_deploy "$RUN_ID"
    else
      warn "no new Deploy run showed up"
      SKIPPED+=("the Deploy run that carries the variables: run this wizard again (it leaves what is done alone, and its last stage clears an older run waiting for production, which a run started by hand would wait behind):  $0")
    fi
  else
    SKIPPED+=("the Deploy run that carries the variables: run this wizard again (it leaves what is done alone, and its last stage clears an older run waiting for production, which a run started by hand would wait behind):  $0")
  fi
  say "Checking the page is behind Access:"
  for host in dev.craigdevjohnson.com next.craigdevjohnson.com; do
    CODE="$(curl -s -o /dev/null -w '%{http_code}' -A family-devices-wizard "https://$host/admin" || true)"
    case "$CODE" in
      30*) ok "$host/admin answers $CODE to $(curl -s -o /dev/null -w '%{redirect_url}' -A family-devices-wizard "https://$host/admin" | cut -d? -f1)" ;;
      503) warn "$host/admin answers 503: that environment has no admin application yet (deploy not through, or ADMIN_EMAILS unset)" ;;
      *)   warn "$host/admin answers '$CODE'" ;;
    esac
  done

  finish
  note "Next, on the devices: docs/family-devices.md, steps 2 to 4 (Family Sharing, each iPad, each iPhone)."
  note "Then, once both iPhones trust the certificate:  $0 inspect"
  printf '\n'
fi

# ── inspect: the second apply ─────────────────────────────────────────────

if [[ "$MODE" == "inspect" ]]; then
  banner "Family devices: turn on HTTPS inspection"

  stage "Check this Mac and the phones"
  preflight
  if [[ ! -f "$TFVARS" ]]; then fail "no $TFVARS; run the first wizard run before this one"; fi
  tf output -json gateway_certificate_status | jq -r '"      certificate \(.id): \(.binding_status), in use \(.in_use), expires \(.expires_on)"'
  if [[ "$(tf output -json gateway_certificate_status | jq -r .binding_status)" != "available" ]]; then
    warn "the certificate is not 'available' at the edge yet; inspection would fail until it is"
  fi
  say "Decrypting before the phones trust the certificate breaks their HTTPS, so:"
  if ! confirm "Do both iPhones have the adult profile installed AND full trust turned on for the Cloudflare Gateway certificate (Settings › General › About › Certificate Trust Settings)?"; then
    fail "do that first (docs/family-devices.md, step 4). Nothing has changed."
  fi

  stage "Plan and apply with inspect_https = true"
  say "This turns on TLS decryption, selects the certificate for inspection, and turns on the"
  say "Gateway proxy (TCP and UDP) so HTTP policies and logs see inside HTTPS from the phones."
  tfvars_set inspect_https true
  plan_and_apply

  stage "Verify"
  CONFIG="$(cf "/accounts/$ACCOUNT_ID/gateway/configuration")"
  DEVICES="$(cf "/accounts/$ACCOUNT_ID/devices/settings")"
  say "  TLS decryption   $(jq -r '.result.settings.tls_decrypt.enabled' <<<"$CONFIG")"
  say "  certificate      $(jq -r '.result.settings.certificate.id // "none"' <<<"$CONFIG")"
  say "  TCP proxy        $(jq -r '.result.gateway_proxy_enabled' <<<"$DEVICES")"
  say "  UDP proxy        $(jq -r '.result.gateway_udp_proxy_enabled' <<<"$DEVICES")"
  tf output -json gateway_certificate_status | jq -r '"  certificate in use  \(.in_use)"'
  say "On an iPhone with the agent on, open a site: Zero Trust › Insights › Logs › HTTP shows the"
  say "full URL, and the padlock in Safari shows a certificate issued by Cloudflare Gateway."
  finish
  note "Optional, later, once the agent has run clean for a while:  $0 lock"
  printf '\n'
fi

# ── lock: the optional third apply ────────────────────────────────────────

if [[ "$MODE" == "lock" ]]; then
  banner "Family devices: lock the agent's switch"

  stage "Check this Mac"
  preflight
  if [[ ! -f "$TFVARS" ]]; then fail "no $TFVARS; run the first wizard run before this one"; fi
  say "lock_client = true makes the root own the account's default device profile: the agent's"
  say "switch is locked and an enrolled phone cannot leave the organisation. The provider also"
  say "sends its own defaults for that profile's other switches, so read the plan against what"
  say "the dashboard shows under Team & Resources › Devices › Device profiles › Default."
  if ! confirm "Has the agent run clean on both iPhones for a while, and do you want the switch locked?"; then
    fail "left alone. Nothing has changed."
  fi

  stage "Plan and apply with lock_client = true"
  tfvars_set lock_client true
  plan_and_apply
  POLICY="$(cf "/accounts/$ACCOUNT_ID/devices/policy")"
  say "  switch locked     $(jq -r '.result.switch_locked' <<<"$POLICY")"
  say "  allowed to leave  $(jq -r '.result.allowed_to_leave' <<<"$POLICY")"
  finish
fi
